import type { Choice, Item } from '../scoring/contracts.ts';
import { MISCONCEPTIONS } from '../scoring/contracts.ts';
import { detectMisconceptions } from '../mastery/observe.ts';

export type HintLevel = 1 | 2 | 3;
export const MAX_HINT_LEVEL = 3;
/** Độ dài tối đa của một gợi ý (kí tự). */
export const HINT_MAX_CHARS = 360;

/** Lần thử / số gợi ý đã xin → mức gợi ý 1..3. */
export function clampHintLevel(attempt: unknown): HintLevel {
  const n = typeof attempt === 'number' ? attempt : typeof attempt === 'string' ? Number(attempt) : NaN;
  if (!Number.isFinite(n) || n <= 1) return 1;
  return n >= 3 ? 3 : 2;
}

type Rec = Record<string, unknown>;
const rec = (v: unknown): Rec => (v && typeof v === 'object' && !Array.isArray(v) ? (v as Rec) : {});
const arr = <T = unknown>(v: unknown): T[] => (Array.isArray(v) ? (v as T[]) : []);
const LETTERS = 'ABCDEFGHIJ';

function choiceText(c: Choice | undefined): string {
  if (!c) return '';
  const t = (c.text ?? '').trim();
  if (t) return t;
  const img = c.image ?? '';
  return img.startsWith('emoji:') ? img.slice(6) : '';
}
const byId = (list: unknown, id: unknown): Choice | undefined => arr<Choice>(list).find((c) => c && c.id === id);

