/* Quan niệm sai                                                       */
/* ------------------------------------------------------------------ */
export interface MisconceptionInfo {
  code: string;
  /** Lời nhắc cho HS. */
  kidHint: string;
  /** Mô tả cho GV (đưa vào lời nhắc của mô hình). */
  text?: string;
}
export type MisconceptionLookup = Record<string, { kidHint?: string; text?: string } | undefined>;

/** Quan niệm sai đầu tiên mà câu trả lời này thể hiện (theo Choice.misconception / key.misconceptions), nếu có lời nhắc. */
export function misconceptionFor(item: Item, response: unknown, lookup: MisconceptionLookup = MISCONCEPTIONS): MisconceptionInfo | null {
  let codes: string[] = [];
  try {
    codes = detectMisconceptions(item, response);
  } catch {
    codes = [];
  }
  for (const code of codes) {
    const m = lookup[code] ?? MISCONCEPTIONS[code];
    const kidHint = (m?.kidHint ?? '').trim();
    if (kidHint) return { code, kidHint, ...(m?.text ? { text: m.text } : {}) };
  }
  return null;
}

/* ------------------------------------------------------------------ */
/* Chuẩn hoá chữ và số                                                 */
/* ------------------------------------------------------------------ */
/** Chữ thường, NFC, bỏ dấu câu (giữ chữ, số, '/', '%'), gộp khoảng trắng. */
export function foldHintText(s: string): string {
  return (s ?? '')
    .normalize('NFC')
    .toLowerCase()
    .replace(/\s*\/\s*/g, '/')
    .replace(/[^\p{L}\p{N}/%]+/gu, ' ')
    .trim()
    .replace(/\s+/g, ' ');
}

/** Tìm `needle` trong `hay` theo ranh giới từ (cả hai đã qua foldHintText). */
function containsWords(hay: string, needle: string): boolean {
  if (!needle) return false;
  return (' ' + hay + ' ').includes(' ' + needle + ' ');
}

/**
 * Các giá trị số mà một chuỗi số có thể mang: "0,5" → 0.5 · "1.250" → 1250 và 1.25 · "1 250" → 1250 · "12.5" → 12.5.
 * Dấu phẩy/chấm theo sau bởi đúng 3 chữ số có thể là dấu tách nghìn; còn lại là dấu thập phân.
 */
export function numberValues(token: string): number[] {
  const t = token.replace(/\s/g, '');
  if (!/^\d+(?:[.,]\d+)*$/.test(t)) return [];
  const out = new Set<number>();
  const add = (s: string) => {
    const n = Number(s);
    if (Number.isFinite(n)) out.add(n);
  };
  const seps = t.replace(/\d/g, '');
  if (!seps) add(t);
  else if (seps.length === 1) {
    const [a, b] = t.split(/[.,]/);
    add(`${a}.${b}`);
    if (b.length === 3 && a.length <= 3 && a !== '0') add(a + b);
  } else {
    const last = Math.max(t.lastIndexOf('.'), t.lastIndexOf(','));
    const head = t.slice(0, last);
    const tail = t.slice(last + 1);
    const groups = head.split(/[.,]/);
    const grouped = groups.slice(1).every((g) => g.length === 3);
    const sameSep = new Set(seps.split('')).size === 1;
    if (grouped && sameSep && tail.length === 3) add(groups.join('') + tail);
    if (grouped && !sameSep) add(`${groups.join('')}.${tail}`);
    if (!grouped || (sameSep && tail.length !== 3)) add(`${head.replace(/[.,]/g, '')}.${tail}`);
  }
  return [...out];
}

/** Mọi số xuất hiện trong văn bản (đã hiểu dấu phẩy thập phân kiểu Việt và dấu tách nghìn). */
export function numbersIn(text: string): number[] {
  const out: number[] = [];
  const src = (text ?? '').replace(/(\d)[\u00a0\u202f ](?=\d{3}(?!\d))/g, '$1');
  const re = /\d+(?:[.,]\d+)*/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(src))) out.push(...numberValues(m[0]));
  return out;
}

const UNITS = ['không', 'một', 'hai', 'ba', 'bốn', 'năm', 'sáu', 'bảy', 'tám', 'chín'];
/** Cách đọc số tự nhiên 0–99 bằng chữ (kèm biến thể: mốt, tư, lăm). */
export function numberWords(n: number): string[] {
  if (!Number.isInteger(n) || n < 0 || n > 99) return [];
  if (n < 10) return [UNITS[n]];
  const ch = Math.floor(n / 10);
  const dv = n % 10;
  const tens = ch === 1 ? 'mười' : `${UNITS[ch]} mươi`;
  if (dv === 0) return [tens];
  const ones = new Set<string>([UNITS[dv]]);
  if (dv === 5) ones.add('lăm');
  if (dv === 1 && ch > 1) ones.add('mốt');
  if (dv === 4 && ch > 1) ones.add('tư');
  return [...ones].map((o) => `${tens} ${o}`);
}

/* ------------------------------------------------------------------ */
/* Đáp án cần giữ kín                                                  */
/* ------------------------------------------------------------------ */
export interface AnswerSecrets {
  /** Chữ của đáp án đúng (đã foldHintText). */
  texts: string[];
  /** Giá trị số của đáp án đúng. */
  numbers: number[];
  /** Nhãn lựa chọn đúng: chữ cái theo vị trí ('B') và id lựa chọn nếu ngắn. */
  labels: string[];
  /** Vị trí (1..n) của lựa chọn đúng — bắt "đáp án thứ hai", "lựa chọn số 2". */
  positions: number[];
  /** Cặp đúng (nối / kéo thả / xếp nhóm): lộ khi cả hai vế cùng nằm trong một câu. */
  pairs: [string, string][];
  /** Thứ tự đúng (sắp xếp / xếp câu): lộ khi các thẻ xuất hiện liền nhau đúng thứ tự. */
  sequences: string[];
}

function addAnswerText(s: AnswerSecrets, raw: unknown): void {
  if (typeof raw !== 'string' && typeof raw !== 'number') return;
  const str = String(raw).trim();
  if (!str) return;
  // Đáp án thuần số chỉ so theo GIÁ TRỊ (tránh bắt nhầm "5" trong "1,5").
  const pureNumber = /^[-+]?\s*\d[\d.,\s]*$/.test(str);
  const folded = foldHintText(str);
  if (!pureNumber && folded && !s.texts.includes(folded)) s.texts.push(folded);
  // "52", "0,5", "96 kg", "1 250 m" → cả giá trị số.
  const lead = /^[-+]?\s*(\d[\d.,\s]*?)(?:\s*[^\d\s.,/][^\d]*)?$/.exec(str);
  if (lead) for (const n of numberValues(lead[1])) if (!s.numbers.includes(n)) s.numbers.push(n);
}

/** Những gì KHÔNG được xuất hiện trong gợi ý, rút từ item + key. Item không có key → rỗng. */
export function answerSecrets(item: Item): AnswerSecrets {
  const s: AnswerSecrets = { texts: [], numbers: [], labels: [], positions: [], pairs: [], sequences: [] };
  const key = rec(item.key);
  const p = rec(item.payload);
  if (!item.key) return s;
  const option = (list: unknown, id: unknown, withLabel: boolean) => {
    const options = arr<Choice>(list);
    const i = options.findIndex((o) => o && o.id === id);
    if (i < 0) return;
    addAnswerText(s, choiceText(options[i]));
    if (withLabel) {
      if (i < LETTERS.length) s.labels.push(LETTERS[i]);
      const oid = String(id);
      if (/^[a-z]$/i.test(oid) && !s.labels.includes(oid.toUpperCase())) s.labels.push(oid.toUpperCase());
      s.positions.push(i + 1);
    }
  };
  const pair = (a: string, b: string) => {
    const x = foldHintText(a);
    const y = foldHintText(b);
    if (x && y && x !== y) s.pairs.push([x, y]);
  };
  switch (item.type) {
    case 'MCQ':
    case 'LISTEN_CHOOSE':
      option(p.options, key.correct, true);
      break;
    case 'MCQ_MULTIPLE':
      for (const id of arr(key.correct)) option(p.options, id, true);
      break;
    case 'SHORT_ANSWER':
      for (const a of arr(key.accepted)) addAnswerText(s, a);
      break;
    case 'MATH_MANIPULATIVE': {
      const v = Number(key.value);
      if (Number.isFinite(v)) {
        s.numbers.push(v);
        if (p.kind === 'clock') {
          const h = Math.floor(v / 60) || 12;
          const mm = v % 60;
          s.texts.push(foldHintText(`${h}:${String(mm).padStart(2, '0')}`), foldHintText(`${h} giờ ${mm} phút`));
          if (mm === 0) s.texts.push(foldHintText(`${h} giờ`));
          if (mm === 30) s.texts.push(foldHintText(`${h} giờ rưỡi`));
        }
      }
      break;
    }
    case 'FILL_IN_PASSAGE':
      for (const v of Object.values(rec(key.blanks))) for (const a of Array.isArray(v) ? v : [v]) addAnswerText(s, a);
      break;
    case 'INLINE_DROPDOWN': {
      const dd = rec(p.dropdowns);
      for (const [b, id] of Object.entries(rec(key.blanks))) option(dd[b], id, false);
      break;
    }
    case 'HOTSPOT':
      for (const id of arr(key.correct)) {
        const r = arr<{ id: string; label?: string }>(p.regions).find((x) => x && x.id === id);
        if (r?.label) addAnswerText(s, r.label);
      }
      break;
    case 'ORDERING':
    case 'SENTENCE_SCRAMBLE': {
      const list = item.type === 'ORDERING' ? p.items : p.words;
      const seq = arr(key.order).map((id) => foldHintText(choiceText(byId(list, id)))).filter(Boolean);
      if (seq.length >= 2) {
        s.sequences.push(seq.join(' '));
        // Nói ra ba thẻ liền nhau đúng thứ tự (hoặc cả dãy nếu ngắn) cũng là lộ.
        for (let i = 0; seq.length > 3 && i + 3 <= seq.length; i++) s.sequences.push(seq.slice(i, i + 3).join(' '));
      }
      break;
    }
    case 'MATCHING':
      for (const [l, r] of Object.entries(rec(key.pairs))) pair(choiceText(byId(p.left, l)), choiceText(byId(p.right, r)));
      break;
    case 'DRAG_DROP':
      for (const [t, z] of Object.entries(rec(key.placement))) pair(choiceText(byId(p.tokens, t)), arr<{ id: string; label: string }>(p.zones).find((x) => x && x.id === z)?.label ?? '');
      break;
    case 'WORD_CLASSIFY':
      for (const [w, g] of Object.entries(rec(key.placement))) pair(choiceText(byId(p.words, w)), arr<{ id: string; label: string }>(p.groups).find((x) => x && x.id === g)?.label ?? '');
      break;
    default:
      break;
  }
  return s;
}

const MARK = '(?:đáp án|phương án|lựa chọn|câu trả lời|kết quả|chọn|ý|câu|ô|thẻ)';
const ORD_WORDS = ['', 'nhất|đầu tiên|đầu|một', 'hai|nhì', 'ba', 'tư|bốn', 'năm', 'sáu', 'bảy', 'tám', 'chín', 'mười'];

/**
 * Văn bản có lộ đáp án đúng của item không? (cần item.key; item không có key → false.)
 * Bắt: chữ của đáp án (theo từ, không phân biệt hoa thường/dấu câu), số bằng giá trị ("0,5" = "0.5" = "0,50", "1.250" = "1250"),
 * số viết bằng chữ sau "là / bằng / được / ra" (0–99), nhãn lựa chọn ("B", "đáp án b", "đáp án thứ hai"),
 * cặp nối đúng trong cùng một câu, dãy thẻ đúng thứ tự. Giới hạn: xem docs/PHASE7_AI_HINT.md.
 */
export function leaksAnswer(text: string, item: Item): boolean {
  const s = answerSecrets(item);
  const raw = (text ?? '').normalize('NFC');
  if (!raw.trim()) return false;
  const folded = foldHintText(raw);

  for (const t of s.texts) if (containsWords(folded, t)) return true;
  for (const q of s.sequences) if (containsWords(folded, q)) return true;

  if (s.numbers.length) {
    const found = numbersIn(raw);
    for (const n of s.numbers) {
      if (found.some((f) => Math.abs(f - n) < 1e-9)) return true;
      for (const w of numberWords(n)) {
        if (new RegExp(`(?:^| )(?:là|bằng|được|ra|còn|có) (?:số )?${w}(?: |$)`, 'u').test(folded)) return true;
      }
    }
  }

  for (const label of s.labels) {
    // Chữ cái in hoa đứng riêng ("B", "(B)", "B.") — chữ thường chỉ tính khi đi sau "đáp án / chọn / ý…".
    if (new RegExp(`(?<![\\p{L}\\p{N}])${label}(?![\\p{L}\\p{N}])`, 'u').test(raw)) return true;
    if (new RegExp(`(?:^| )${MARK} (?:đúng )?(?:là )?${label.toLowerCase()}(?: |$)`, 'u').test(folded)) return true;
  }
  for (const pos of s.positions) {
    const words = ORD_WORDS[pos];
    const alt = words ? `${pos}|${words}` : String(pos);
    if (new RegExp(`(?:^| )${MARK} (?:đúng )?(?:là )?(?:thứ|số) (?:${alt})(?: |$)`, 'u').test(folded)) return true;
  }

  if (s.pairs.length) {
    for (const sentence of raw.split(/[.!?…\n;]+/)) {
      const f = foldHintText(sentence);
      if (!f) continue;
      for (const [a, b] of s.pairs) if (containsWords(f, a) && containsWords(f, b)) return true;
    }
  }
  return false;
}

/** Dọn câu trả lời của mô hình: bỏ markdown, ngoặc kép bọc ngoài, xuống dòng; cắt còn tối đa 3 câu / HINT_MAX_CHARS. */
export function tidyHintText(text: string): string {
  let t = (text ?? '')
    .replace(/```[\s\S]*?```/g, ' ')
    .replace(/[*_#`>]+/g, '')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/^(?:gợi ý|hint)\s*[:：-]\s*/i, '')
    .replace(/^["“”'‘’\s]+|["“”'‘’\s]+$/g, '');
  const parts = t.match(/[^.!?…]+[.!?…]+|[^.!?…]+$/g) ?? [];
  if (parts.length > 3) t = parts.slice(0, 3).join('').trim();
  if (t.length > HINT_MAX_CHARS) {
    const cut = t.slice(0, HINT_MAX_CHARS);
    const end = Math.max(cut.lastIndexOf('. '), cut.lastIndexOf('! '), cut.lastIndexOf('? '));
    t = end > 40 ? cut.slice(0, end + 1) : cut.slice(0, cut.lastIndexOf(' ')).trim() + '…';
  }
  return t;
}

/* ------------------------------------------------------------------ */
/* Gợi ý theo quy tắc (không cần AI)                                   */
/* ------------------------------------------------------------------ */
type Family = 'choice' | 'listen' | 'number' | 'text' | 'order' | 'group' | 'fill' | 'spot' | 'other';

function familyOf(item: Item): Family {
  switch (item.type) {
    case 'MCQ':
    case 'MCQ_MULTIPLE':
      return 'choice';
    case 'LISTEN_CHOOSE':
      return 'listen';
    case 'MATH_MANIPULATIVE':
      return 'number';
    case 'SHORT_ANSWER':
      return item.subject === 'toan' || rec(item.payload).inputMode === 'numeric' ? 'number' : 'text';
    case 'ORDERING':
    case 'SENTENCE_SCRAMBLE':
      return 'order';
    case 'MATCHING':
    case 'DRAG_DROP':
    case 'WORD_CLASSIFY':
      return 'group';
    case 'FILL_IN_PASSAGE':
    case 'INLINE_DROPDOWN':
      return 'fill';
    case 'HOTSPOT':
      return 'spot';
    default:
      return 'other';
  }
}

